case "EXPLORE_DISABLED":
      return {
        action: "Return to Boundary Review, complete the required decisions, and activate the exact reviewed digest.",
        preserved,
      };

case "EXPLORE_PROFILE_FORBIDDEN":
      return {
        action: "Relaunch through the local guided start path, or configure an explicit Development or Staging profile through the established operator route before activating a new digest.",
        preserved,
      };

case "EXPLORE_BOUNDARY_MISMATCH":
      return {
        action: "Choose Rescan and show changes. Review the semantic drift before activating a new digest.",
        preserved,
      };

case "EXPLORE_ROLE_UNSAFE":
      return {
        action: "Reconnect with a dedicated verified SELECT-only, non-owner source credential that has no elevated/global or RLS-bypass authority, then rescan.",
        preserved,
      };

case "EXPLORE_SCOPE_FORBIDDEN":
      {
        const missing = error instanceof ScopedExploreError
          && Array.isArray(error.details?.missing_bindings)
          ? error.details.missing_bindings
            .filter(isRecord)
            .map((binding) => typeof binding.env === "string" ? binding.env : undefined)
            .filter((value): value is string => Boolean(value))
          : [];
        const namedBindings = missing.length > 0 ? missing.join(" and ") : "the trusted scope environment values";
        return {
          action: `Configure ${namedBindings} in the operator-owned environment, then retry. Do not enter identity values into an analytics question or model prompt.`,
          preserved,
        };
      }

case "EXPLORE_SOURCE_UNAVAILABLE":
      {
        const sourceRequirement = scopedExploreSourceRequirement(error);
        if (sourceRequirement) {
          return {
            action: `Set ${sourceRequirement.environment} in the terminal that launched Workbench, then retry. Runner reads the value from the process environment and does not write it to project files.`,
            preserved,
          };
        }
      }
      return {
        action: "Restore the reviewed read-only database connection and retry. Runner will recheck role and schema posture.",
        preserved,
      };

case "EXPLORE_RESPONSE_TOO_LARGE":
      return {
        action: "Reduce selected fields or measures, or the original query's row or group limit. Waiting does not increase a fixed response limit, and smaller delivery pages do not reduce the admission estimate. The request must still satisfy the disclosure controls; do not widen the boundary to bypass a limit.",
        preserved,
      };

case "EXPLORE_BUDGET_UNAVAILABLE":
      return {
        action: "Check the local budget store and restore the reservation state before retrying. Unavailable state does not establish exhaustion; changing the query or waiting for an allowance is not a repair for unavailable storage.",
        preserved,
      };

case "EXPLORE_PRIVACY_BUDGET_EXHAUSTED":
      return {
        action: "Follow the exact disclosure-control refusal. Smaller delivery pages, another cursor, or a new MCP session do not reset that control. Wait only where the documented rolling allowance permits it; do not widen the boundary or raise throughput limits to bypass it.",
        preserved,
      };

case "EXPLORE_RATE_LIMITED":
      return {
        action: "Wait for the documented rolling request-rate allowance. A new session does not reset the trusted-scope limit; do not widen the boundary to bypass it.",
        preserved,
      };

case "EXPLORE_PLAN_INVALID":
      return {
        action: "Use only the resources, fields, relationships, and bounds shown in Explore reviewed data.",
        preserved,
      };

case "EXPLORE_TRANSPORT_FORBIDDEN":
      return {
        action: "Use this secured loopback Workbench or the local stdio authoring configuration.",
        preserved,
      };

case "year_to_date": {
      const duration = end.getTime() - start.getTime();
      return range(new Date(start.getTime() - duration), start);
    }

serialized.replace(token, (match, offset: number) => {
    if (match.startsWith('"')) {
      const isKey = /^\s*:/.test(serialized.slice(offset + match.length));
      return style(isKey ? "1;36" : "1;32", match);
    }
    if (/^-?\d/.test(match)) return style("1;33", match);
    if (match === "true" || match === "false") return style("1;35", match);
    return style("2", match);
  })

value.replace(token, (match, offset: number) => {
    if (offset === 0) return style("1;32", match);
    if (match.startsWith("--")) return style("1;36", match);
    if (match.startsWith("<")) return style("1;33", match);
    if (match.startsWith("'")) return style("1;35", match);
    return match;
  })

value.replace(token, (match) => {
    if (match.startsWith("--") || match.startsWith("/*")) return style("2", match);
    if (match.startsWith("'")) return style("1;32", match);
    if (match.startsWith("sha256:")) return style("2", match);
    if (/^-?\d/u.test(match)) return style("1;33", match);
    if (/^[A-Z][A-Z0-9_]*$/u.test(match)) return style("1;36", match);
    if (/^[A-Za-z_][A-Za-z0-9_]*\./u.test(match)) return style("1;34", match);
    return style("1;35", match);
  })

statement.replace(sqlToken, (match) => {
    const upper = match.toUpperCase();
    if (match.startsWith("--") || match.startsWith("/*")) return style("2", match);
    if ((match.startsWith("$") && match.endsWith("$") && !/^\$\d+$/.test(match))
      || match.startsWith("'")) return style("1;35", match);
    if (match.startsWith('"') || match.startsWith("`") || match.startsWith("[")) {
      return style("1;32", match);
    }
    if (match === "?" || /^\$\d+$/.test(match) || /^:[A-Za-z_]/.test(match)) {
      return style("1;33", match);
    }
    if (/^-?\d/.test(match)) return style("1;33", match);
    if (sqlFunctions.has(upper)) return style("1;34", match);
    if (sqlTypes.has(upper)) return style("1;35", match);
    if (sqlKeywords.has(upper)) return style("1;36", match);
    return match;
  })
